// Tipos básicos: se anotan con «: tipo» después del nombre
const pesoKg: number = 12.5;
const destino: string = "Rosario";
const urgente: boolean = false;
const pesos: number[] = [12.5, 8, 30];
const par: [string, number] = ["CABA", 120];   // tupla: largo y tipos fijos

// Alias: un nombre para un tipo
type Zona = "CABA" | "GBA" | "Interior";
type Coordenadas = { lat: number; lng: number };

// Interfaz: la forma de un objeto
interface Bulto {
  readonly id: number;   // no se puede reasignar
  pesoKg: number;
  zona: Zona;
  nota?: string;         // el «?» lo hace opcional
}

const b: Bulto = { id: 1, pesoKg, zona: "GBA" };
b.pesoKg = 13;                              // permitido
b.id = 2;                                   // error: es de solo lectura
b.zona = "Mendoza";                         // error: no es una Zona
const mal: Bulto = { id: 3, pesoKg: 5 };    // error: falta zona

// Unión: «uno u otro»
function aKilos(peso: number | string): number {
  if (typeof peso === "string") {
    return Number(peso.replace(",", "."));   // acá TypeScript sabe que es string
  }
  return peso;                                // y acá, que es number
}

// Unión etiquetada: el campo «tipo» dice qué forma tiene el resto
type Evento =
  | { tipo: "escaneo"; bultoId: number }
  | { tipo: "entrega"; bultoId: number; firma: string }
  | { tipo: "falla"; motivo: string };

function describir(e: Evento): string {
  switch (e.tipo) {
    case "escaneo":
      return `escaneado ${e.bultoId}`;
    case "entrega":
      return `entregado ${e.bultoId}, firma de ${e.firma}`;
    case "falla":
      return `falla: ${e.motivo}`;
    default: {
      const imposible: never = e;   // si llega acá, quedó un caso sin cubrir
      return imposible;
    }
  }
}

type ConGps = { lat: number; lng: number };
type Camioneta = { patente: string } & ConGps;   // «los dos a la vez»

const c: Camioneta = { patente: "AB123CD", lat: -34.6, lng: -58.4 };

// Sin genéricos hay que elegir: un tipo fijo o «any» (que apaga la revisión)
function primeroAny(xs: any[]): any {
  return xs[0];
}

// Con un genérico, «T» es un hueco que se completa en cada uso
function primero<T>(xs: T[]): T | undefined {
  return xs[0];
}

const a = primeroAny([12, 8]);       // a: any    (se perdió el tipo)
const n = primero([12, 8]);          // n: number | undefined
const z = primero(["CABA", "GBA"]);  // z: string | undefined

a.cualquierCosa();   // compila: any acepta todo
n.toFixed();         // error: n puede ser undefined
z?.toUpperCase();    // ok: «?.» solo sigue si hay valor

const crudo: any = JSON.parse('{"pesoKg":"12"}');
console.log(crudo.pesoKg.toFixed(1));      // compila; falla al ejecutar

const seguro: unknown = JSON.parse('{"pesoKg":"12"}');
console.log(seguro.pesoKg);                // error: hay que comprobar antes de usarlo

if (typeof seguro === "object" && seguro !== null && "pesoKg" in seguro) {
  console.log(typeof seguro.pesoKg);       // ahora sí: se puede mirar el campo
}

