import { z } from "zod";

interface Bulto {
  id: number;
  pesoKg: number;
  zona: string;
}

// Lo que mandó «el servidor». El peso vino como texto y nadie se enteró.
const texto = '{"id": 7, "pesoKg": "12.5", "zona": "GBA"}';

// 1) Con «as»: el compilador se calla, porque le dijiste que sabés lo que hacés.
const b1 = JSON.parse(texto) as Bulto;
console.log("as:", b1.pesoKg + 1);              // se esperaba 13.5

// 2) Con un esquema de zod: se comprueba en ejecución.
const EsquemaBulto = z.object({
  id: z.number(),
  pesoKg: z.number(),
  zona: z.string(),
});
type BultoValidado = z.infer<typeof EsquemaBulto>;   // el tipo sale del esquema

const r = EsquemaBulto.safeParse(JSON.parse(texto));
if (r.success) {
  const b2: BultoValidado = r.data;
  console.log("zod ok:", b2.pesoKg + 1);
} else {
  console.log("zod rechazó:", r.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`));
}

// Lo que llega de afuera es texto: JSON.parse solo garantiza que es JSON válido.
const texto = '{"id": 7, "pesoKg": "12.5", "zona": "Mendoza"}';
const datos = JSON.parse(texto);

// Un validador mínimo: una función por campo que dice si el valor sirve.
const ZONAS = ["CABA", "GBA", "Interior"];
const esquema = {
  id:     (v) => typeof v === "number" && Number.isInteger(v),
  pesoKg: (v) => typeof v === "number" && v > 0,
  zona:   (v) => ZONAS.includes(v),
};

function validar(obj) {
  if (typeof obj !== "object" || obj === null) return ["no es un objeto"];
  const errores = [];
  for (const campo of Object.keys(esquema)) {
    if (!(campo in obj)) errores.push(`${campo}: falta`);
    else if (!esquema[campo](obj[campo])) errores.push(`${campo}: valor inválido (${JSON.stringify(obj[campo])})`);
  }
  return errores;
}

console.log("Sin validar, el peso más 1 da:", datos.pesoKg + 1);
const errores = validar(datos);
console.log(errores.length === 0 ? "El dato sirve" : "Rechazado: " + errores.join("; "));
